// Vendors the MediaPipe Tasks Vision WASM runtime into public/ so the pose
// landmarker loads from same-origin static files instead of a third-party
// CDN. Runs automatically after `npm install` (see package.json). Not
// committed to git — regenerated by every install, same as node_modules.
import { cpSync, existsSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const src = join(__dirname, '..', 'node_modules', '@mediapipe', 'tasks-vision', 'wasm')
const dest = join(__dirname, '..', 'public', 'mediapipe', 'wasm')

if (!existsSync(src)) {
  console.warn('[copy-mediapipe-wasm] source not found, skipping:', src)
  process.exit(0)
}

mkdirSync(dirname(dest), { recursive: true })
cpSync(src, dest, { recursive: true })
console.log('[copy-mediapipe-wasm] vendored MediaPipe wasm runtime into public/mediapipe/wasm')
